<?php declare(strict_types=1);use FastWebsite\Core\View;$media=static function(mixed$path)use($baseUrl):?string{if(!is_string($path)||trim($path)===''||preg_match('#^(?:https?:)?//#i',$path)===1)return null;return$baseUrl.ltrim(preg_replace('#^public/#','',str_replace('\\','/',$path))??$path,'/');};$image=$media($unit['hero_path']);$name=static fn(array$m):string=>trim(implode(' ',array_filter([$m['honorific_title'],$m['first_name'],$m['middle_name'],$m['last_name']])));?>
<section class="page-title-hero<?=$image?' has-image':''?>"><?php if($image):?><img class="page-title-hero-image" src="<?=View::escape($image)?>" alt=""><?php endif;?><div class="shell"><a class="back-link" href="<?=View::escape($baseUrl)?>research">← Research</a><p class="eyebrow"><?=View::escape($unit['type_name'])?></p><h1><?=View::escape($unit['name'])?></h1><?php if($unit['acronym']):?><p class="lead"><?=View::escape($unit['acronym'])?></p><?php endif;?></div></section>
<section class="section"><div class="shell public-record-grid"><div class="public-record-main"><?php foreach(['Overview'=>'overview','Research focus'=>'research_focus','Facilities and capabilities'=>'capabilities','Student opportunities'=>'student_opportunities','Industry and community services'=>'industry_services']as$heading=>$field):?><?php if(is_string($unit[$field])&&trim($unit[$field])!==''):?><section class="public-content-section"><h2><?=$heading?></h2><div class="prose"><?=View::richText($unit[$field])?></div></section><?php endif;?><?php endforeach;?><?php if($projects!==[]):?><section class="public-content-section"><h2>Research projects</h2><div class="department-card-grid"><?php foreach($projects as$p):?><?php $pImage=$media($p['hero_path']);?><article class="department-card"><?php if($pImage):?><img class="department-card-image" src="<?=View::escape($pImage)?>" alt="<?=View::escape($p['hero_alt_text']?:$p['title'])?>"><?php endif;?><div><p class="eyebrow"><?=View::escape(ucfirst($p['project_status']))?> project</p><h3><a href="<?=View::escape($baseUrl)?>research/projects/<?=View::escape($p['slug'])?>"><?=View::escape($p['title'])?></a></h3><?php if($p['summary']):?><p><?=View::escape(mb_strimwidth((string)$p['summary'],0,160,'…'))?></p><?php endif;?><a class="text-link" href="<?=View::escape($baseUrl)?>research/projects/<?=View::escape($p['slug'])?>">View project →</a></div></article><?php endforeach;?></div></section><?php endif;?>
<?php if($facilities!==[]):?><section class="public-content-section"><h2>Facilities</h2><div class="staff-card-grid"><?php foreach($facilities as$facility):?><article class="staff-card"><div><p class="eyebrow"><?=View::escape(ucwords(str_replace('_',' ',(string)$facility['facility_type'])))?></p><h3><?=View::escape($facility['name'])?></h3><?php if($facility['description']):?><p><?=View::escape(mb_strimwidth(strip_tags((string)$facility['description']),0,150,'…'))?></p><?php endif;?></div></article><?php endforeach;?></div></section><?php endif;?>
<?php if($equipment!==[]):?><section class="public-content-section"><h2>Equipment</h2><div class="staff-card-grid"><?php foreach($equipment as$item):?><article class="staff-card"><div><p class="eyebrow"><?=View::escape(ucwords(str_replace('_',' ',(string)$item['availability_status'])))?></p><h3><?=View::escape($item['name'])?></h3><?php if($item['manufacturer']||$item['model']):?><p><?=View::escape(implode(' · ',array_filter([$item['manufacturer'],$item['model']])))?></p><?php endif;?></div></article><?php endforeach;?></div></section><?php endif;?>
<?php if($members!==[]):?><section class="public-content-section"><h2>Research team</h2><div class="staff-card-grid"><?php foreach($members as$member):?><?php $profile=$media($member['profile_path']);?><article class="staff-card"><?php if($profile):?><img src="<?=View::escape($profile)?>" alt="<?=View::escape($member['profile_alt_text']?:$name($member))?>"><?php endif;?><div><p class="eyebrow"><?=View::escape($member['role_title']?:ucwords(str_replace('_',' ',$member['membership_role'])))?></p><h3><a href="<?=View::escape($baseUrl)?>staff/<?=View::escape($member['staff_slug'])?>"><?=View::escape($name($member))?></a></h3><?php if($member['short_biography']):?><p><?=View::escape(mb_strimwidth($member['short_biography'],0,150,'…'))?></p><?php endif;?></div></article><?php endforeach;?></div></section><?php endif;?></div>
<aside class="public-contact-card"><p class="eyebrow">Research unit</p><h2><?=View::escape($unit['acronym']?:$unit['type_name'])?></h2><?php if($unit['department_name']):?><p><strong>Lead department</strong><br><?php if($unit['department_slug']):?><a href="<?=View::escape($baseUrl)?>departments/<?=View::escape($unit['department_slug'])?>"><?=View::escape($unit['department_name'])?></a><?php else:?><?=View::escape($unit['department_name'])?><?php endif;?></p><?php endif;?><?php if($unit['email']):?><p><strong>Email</strong><br><a href="mailto:<?=View::escape($unit['email'])?>"><?=View::escape($unit['email'])?></a></p><?php endif;?><?php if($unit['phone']):?><p><strong>Phone</strong><br><?=View::escape($unit['phone'])?></p><?php endif;?><?php if($unit['building']||$unit['room']):?><p><strong>Location</strong><br><?=View::escape(implode(', ',array_filter([$unit['building'],$unit['room']])))?></p><?php endif;?><?php if($unit['website_url']):?><p><a class="button button-primary" href="<?=View::escape($unit['website_url'])?>">Visit research website</a></p><?php endif;?></aside></div></section>
